<script setup>
import {ref,onUnmounted} from 'vue'
import DailyGift from './DailyGift.vue'
import AdminGiftInbox from './AdminGiftInbox.vue'
const daily=ref(null),inbox=ref(null),dialog=ref(null),tab=ref('daily'),count=ref(0)
function open(value='daily'){tab.value=value;if(value==='daily')daily.value?.refresh();else{inbox.value?.refresh();inbox.value?.markRead()}if(!dialog.value.open)dialog.value.showModal()}
function arrived(){if(!document.querySelector('dialog[open]'))open('inbox')}
onUnmounted(()=>dialog.value?.close())
</script>
<template><button class="profile-link gift-center-launch" :aria-label="'선물/선물함 · 미수령 '+count+'건'" @click="open()">🎁 선물/선물함 <b v-if="count" class="unread-badge">{{count}}</b></button><dialog ref="dialog" class="gift-center" aria-label="선물/선물함"><header><h2>선물/선물함</h2><button class="light" aria-label="선물/선물함 닫기" @click="dialog.close()">✕</button></header><div class="gift-center-tabs" role="tablist"><button role="tab" :aria-selected="tab==='daily'" :class="{selected:tab==='daily'}" @click="open('daily')">오늘의 선물</button><button role="tab" :aria-selected="tab==='inbox'" :class="{selected:tab==='inbox'}" @click="open('inbox')">받은 선물함 {{count?'('+count+')':''}}</button></div><div v-show="tab==='daily'"><DailyGift ref="daily" embedded/></div><div v-show="tab==='inbox'"><AdminGiftInbox ref="inbox" embedded @count="count=$event" @attention="arrived" @close="dialog.close()"/></div></dialog></template>
<style scoped>.gift-center{box-sizing:border-box;width:min(660px,calc(100vw - 28px));max-height:88dvh;overflow:auto;padding:20px;border:3px solid var(--rpg-edge);border-radius:12px;background:var(--rpg-paper);color:var(--rpg-ink);box-shadow:0 6px var(--rpg-shadow)}.gift-center::backdrop{background:#172b4099}.gift-center>header{display:flex;justify-content:space-between;align-items:center;padding:0!important;margin:0!important;border:0!important;gap:10px}.gift-center h2{font-size:20px;margin:0}.gift-center>header button{padding:7px;min-width:36px}.gift-center-tabs{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}.gift-center-tabs button{min-height:42px;font-size:13px;padding:10px}.gift-center-launch{display:inline-flex;align-items:center;justify-content:center;white-space:nowrap;gap:5px}.gift-center :deep(.embedded-gift){display:block;width:100%;max-height:none;margin:0;padding:10px 0;border:0;border-radius:0;box-shadow:none;background:transparent}@media(max-width:600px){.gift-center{padding:16px}.gift-center-tabs button{font-size:11px;padding:8px}.gift-center h2{font-size:17px}}</style>
